INSERT INTO `achievement_locale` (`ID`, `locale`, `Description_lang`, `Title_lang`, `Reward_lang`, `VerifiedBuild`) VALUES
(63325, 'esMX', 'Obtén 5 motas de omnindagación para usar en el folio del Omnium.', 'Estudios del folio del Omnium', 'Decoración de recompensa: Simulación del Omnium Caminante del Sol', 68974),
(62903, 'esMX', 'Disipa 5 tormentas en Val.', 'Inclemencias climáticas: Val', 'Mascota de recompensa: Desbloquea la opción de comprar a Keith paletas de pescado', 68974),
(63343, 'esMX', 'Anota un gol con la pelota de práctica en Lunargenta mientras usas un tabardo de participación.', '¡Gol!', 'Decoración de recompensa: Prestigioso orbe de Azeroth, Orgullo de la Horda enmarcado y Orgullo de la Alianza enmarcado', 68974),
(61336, 'esMX', 'Honra las llamas de Midnight.', 'Celador de llamas de Midnight', '', 68974),
(61335, 'esMX', 'Honra las llamas de Midnight.', 'Vigilante de llamas de Midnight', '', 68974),
(61936, 'esMX', 'Derrota a la vanguardia cegada por la Luz cuando toda la banda tenga Aura máxima en la Aguja del Vacío en dificultad normal o superior.', 'Acumulación de aura', '', 68974),
(61911, 'esMX', 'Derrota a Vaelgor y Ezzorak después de que todos los jugadores rompan los vínculos de todas las nulizonas en los 3 segundos posteriores en la Aguja del Vacío en dificultad normal o superior.', '¡Preparados, listos, corten!', '', 68974),
(61514, 'esMX', 'Derrota al Rey Caído Salhadaar después de que todos se tomen un momento para /arrodillarse frente a él antes de que comience la batalla en Aguja del Vacío en dificultad normal o superior.', 'De rodillas', '', 68974),
(61381, 'esMX', 'Derrota a Belo\'ren, hijo de Al\'ar, después de infundir el huevo de la Fuente del Sol con magia de la Luz y del Vacío en Marcha sobre Quel\'Danas en dificultad normal o superior.', 'Infusión dual', '', 68974),
(61346, 'esMX', 'Derrota a la Corona del Cosmos después de matar a la monstruosidad carnosa y devolverle toda su carne a la vacuidad en la Aguja del Vacío en dificultad normal o superior.', 'Volveremos a verlo, te lo aseguro', '', 68974),
(61611, 'esMX', 'Supera Cae la medianoche en Marcha sobre Quel\'Danas en dificultad mítica en un grupo de hermandad.', 'Mítico: Hermandad en Cae la medianoche', '', 68974),
(61380, 'esMX', 'Completa los siguientes logros de banda.', 'Gloria del asaltante de Midnight', 'Montura: Torturador tenebroso', 68974),
(62874, 'esMX', 'Completa los siguientes logros:', 'Un viaje a través de las estrellas', 'Recompensa: Desbloquea la opción de comprar el Mecarmazón forjabisal', 68974);
INSERT INTO `adventure_journal_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `ButtonText_lang`, `RewardDescription_lang`, `ContinueDescription_lang`, `VerifiedBuild`) VALUES
(909, 'esMX', 'Folio del Omnium: información nueva', 'Los magísteres disponen de información adicional que podría servir para potenciar más runas en el folio del Omnium.', 'Aceptar misión', 'Otorga una mota de omnindagación para potenciar otra runa en el folio del Omnium.', '', 68974);
INSERT INTO `area_table_locale` (`ID`, `locale`, `AreaName_lang`, `VerifiedBuild`) VALUES
(15966, 'esMX', 'Cubil de Predaxas', 68974);
INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(4618, 'esMX', 'MODO RELAJACIÓN: ACTIVADO.\nNIVEL DE RELAJACIÓN: MÁXIMO.\nTEMPERATURA INTERNA: BAJA.', '|cFFFFD200Promoción|r |n', 68974),
(4617, 'esMX', 'DIRECTIVA PRINCIPAL: REALIZAR HAZAÑAS HEROICAS.\nHAZAÑAS HEROICAS PREFERIDAS: EMOCIONANTES.\nSEGUNDA DIRECTIVA: CONVERTIRSE EN HÉROE.\nHÉROE PREFERIDO: GRANDE.', '|cFFFFD200Promoción|r |n', 68974),
(4949, 'esMX', 'Un vestigio persistente de los intentos de Fyrakk por corromper Amirdrassil.', '|cFFFFD200Vendedor: |rXydan|n|cFFFFD200Zona: |rValdrakken|n|cFFFFD200Costo: |r2200|Hcurrency:1166|h|TInterface\\ICONS\\PVECurrency-Justice.blp:0|t|h', 68974),
(5074, 'esMX', 'A diferencia de la mayoría de los abisarios de la Tormenta del Vacío, Silento prefiere la paz y la quietud del silencio. Aun si eso significa silenciar a sus pares más ruidosos.', '|cFFFFD200Logros:|r Enfrentamiento exitoso: Val y Enfrentamiento exitoso: Naigtal|n|cFFFFD200Vendedor: |rKifaan|n|cFFFFD200Zonas: |rVal o Naigtal|n|cFFFFD200Costo: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(5073, 'esMX', 'En un esfuerzo por vivir a la altura de su linaje, esta pequeñita está lista para arrasar con todo a su paso. Primero se ocupará de las arañas pequeñas, y después buscará presas más grandes.', '|cFFFFD200Logro:|r Carnicero ultradonte|n|cFFFFD200Vendedor: |rKifaan|n|cFFFFD200Zonas: |rVal o Naigtal|n|cFFFFD200Costo: |r15|Hcurrency:3316|h|TInterface\\ICONS\\INV_112_RaidTrinkets_VoidPrism.BLP:0|t|h', 68974),
(4898, 'esMX', 'Los peces congelados son el alimento favorito de Keith. Si consigues peces congelados, también conseguirás un nuevo amigo.', '|cFFFFD200Logro:|r Inclemencias climáticas: Val|n|cFFFFD200Vendedor: |rKifaan|n|cFFFFD200Zona: |rNaigtal o Val|n|cFFFFD200Costo: |r50|Hitem:238365|h|TInterface\\ICONS\\INV_Misc_Fish_41.blp:0|t|h |n|n', 68974);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(317639, 'esMX', 'El comandante Tala\'saan se quita su capa veloluz y da un paso al frente.', '', 68974),
(314421, 'esMX', '¡ARGH!', '', 68974),
(314420, 'esMX', '¡SOBRINO, CUIDADO!', '', 68974),
(314419, 'esMX', '¡NI HASH\'EY!', '', 68974),
(314418, 'esMX', 'Con este poder, no necesitamo\' loa,', '', 68974),
(314417, 'esMX', '¡No!', '', 68974),
(314416, 'esMX', '¡Suéltala!', '', 68974),
(314415, 'esMX', '¡Eso e\' magia negra!', '', 68974),
(314414, 'esMX', '¡Zul\'jan!', '', 68974),
(314413, 'esMX', '(gruñe)', '', 68974),
(314412, 'esMX', 'Sin duda es... la llave de...', '', 68974),
(314411, 'esMX', '¡La encontré!', '', 68974),
(314410, 'esMX', '¡Ah!', '', 68974),
(314408, 'esMX', 'te aseguro... que lo entenderá.', '', 68974),
(314407, 'esMX', 'Una vez que haya\' conseguido el poder de Ula\'tek,', '', 68974),
(314406, 'esMX', 'Toma la llave, Zul\'jan.', '', 68974),
(314405, 'esMX', 'Cuando vea a nuestro tío...', '', 68974),
(314404, 'esMX', 'Lo\' loa la tienen completamente bajo su poder...', '', 68974),
(314403, 'esMX', '¿Y qué hay de mi hermana?', '', 68974),
(314402, 'esMX', 'Para terminar lo que empezamo\' con tu abuelo.', '', 68974),
(314401, 'esMX', 'y liberarlo de la\' farsa\' de los loa.', '', 68974),
(314400, 'esMX', 'Para proteger el futuro de nuestro pueblo', '', 68974),
(314399, 'esMX', 'y necesito de tu ayuda, Zul\'jan.', '', 68974),
(314398, 'esMX', 'Malacrass,', '', 68974),
(314397, 'esMX', 'Sí...', '', 68974),
(314396, 'esMX', 'Entonce\' debes ser...', '', 68974),
(314395, 'esMX', '¿Tú... conocía\' a mi abuelo?', '', 68974),
(314394, 'esMX', 'Zul\'jin y yo intentamo\' cambiarlo...', '', 68974),
(314393, 'esMX', 'Por desgracia, este e\' el destino de nuestro pueblo.', '', 68974),
(314392, 'esMX', '... ¿pero dónde estaban cuando exhaló su último aliento?', '', 68974),
(314391, 'esMX', 'Dedicó su vida a su\' loa...', '', 68974),
(314390, 'esMX', 'Trágico.', '', 68974),
(314389, 'esMX', 'No, no, no, nunca quise...', '', 68974),
(314388, 'esMX', 'No...', '', 68974),
(314387, 'esMX', 'Está muerto, Zul\'jan.', '', 68974),
(314386, 'esMX', '¡TÍO!', '', 68974),
(314385, 'esMX', '¡¿Tío?!', '', 68974),
(314384, 'esMX', '(tose)', '', 68974),
(310355, 'esMX', 'Yo buscaré la pieza faltante en Aguja de la Estrella del Alba. Ven conmigo cuando puedas, $n. Buena suerte, Rommath.', '', 68974),
(317801, 'esMX', '<Tala\'saan considera la pregunta, su expresión se vuelve distante por un momento.>\n\nLa capitana Fareeya no se unirá a esta operación.\n\nYo actúo como su representante ante los Templeluz desplegados en la misión de Maella.\n\nTras la pérdida del alto exarca y de muchos otros, el Ejército de la Luz necesita su liderazgo ahora más que nunca.\n\nPor fortuna, no estamos completamente solos. Como viste, Baraat e Y\'mera se unieron a nosotros.\n\nEnaara autorizó a ambos tras muchas protestas, pero ella también se quedará atrás con Sorvos y la capitana.', '', 68974),
(317797, 'esMX', '<La expresión de Tala\'saan se tensa.>\n\nPerdimos a muchos de mis hermanos y hermanas... en el vórtice desgarrador de la Aguja del Vacío.\n\nMuchos otros sufrieron heridas que van más allá de lo físico.\n\nSé lo que les ocurrió a muchos de los que estaban dentro de la aguja, $n. Tú también lo viste, ¿verdad? Ira... confusión... desesperación.\n\nPerdimos a muchas buenas almas en esta guerra. No podía pedirle a Fareeya que sacrificara más de lo que ya sacrificó.', '', 68974),
(317795, 'esMX', 'Soy Tala\'saan, comandante de los veloluz en el Ejército de la Luz.\n\nPor pedido de la avizora de fallas Maella, me uní a su misión de perseguir a estas fuerzas del Vacío y los hal\'hadar.\n\nNuestra historia con estos enemigos es complicada, pero tenemos aptitudes para viajar a reinos desconocidos.\n\nTodos los que ves reunidos aquí están entre los mejores de la unidad veloluz.', '', 68974),
(317656, 'esMX', '', 'Tul\'amar aprieta los dientes y se queda en silencio un momento. Su ojo bueno se posa rápidamente sobre ti y luego voltea hacia Tala\'saan.', 68974),
(317572, 'esMX', 'Seguiré de cerca a mi… bueno, mejor dicho, nuestro nuevo peón.', '', 68974),
(317571, 'esMX', 'Nuestra labor no está completa, pero no se preocupen, Impotus no se interpondrá en nuestro camino. Se encerrará en la Acrópolis a saborear su victoria.', '', 68974),
(317109, 'esMX', 'Esta pocilga helada es frágil. Hay otros mundos que serían muchísimo más sencillos... más ideales.', '', 68974),
(316762, 'esMX', 'La avizora de fallas Maella nos pidió que acompañáramos a sus fuerzas en esta expedición.\n\nVeraan constituye una pieza valiosa en esta misión por sus conocimientos sobre el Vacío y las operaciones de los hal\'hadar.\n\n¿Y yo? Bueno, ¡nunca se sabe cuándo se necesita a un tecnomante para desmontar algo!', '', 68974),
(316750, 'esMX', '', 'Según los archivos de Antorus, la presencia de la Legión aquí, en Val, era escasa. No me imagino por qué.\n\nGran parte de este mundo está protegido por enormes tormentas de granizo, capaces de perforar los cascos de las naves de la Legión.\n\nAl menos dos naves de invasión se perdieron mientras intentaban conquistar este mundo.\n\nCon el tiempo establecieron algunas fortalezas, aunque no eran más que puestos avanzados remotos.\n\nAl parecer, a quienes se destinaba a los puestos avanzados de Val se les enviaba aquí como castigo por sus continuos fracasos.', 68974),
(316562, 'esMX', '', '<La archimaga Y\'mera parece concentrada en su tarea: sus manos se mueven a toda velocidad mientras introduce símbolos rúnicos en la consola.>\n\nLa energía del Vacío que se percibe al sur proviene de la Acrópolis. \n\nSegún estas lecturas, la fortaleza se adentra a gran profundidad bajo el hielo.', 68974),
(316520, 'esMX', '', 'Los Illidari conocen este infierno congelado mejor que nadie. La Legión lo llamaba \"Val\" y utilizaba sus temperaturas gélidas para interrogar a los prisioneros.\n\nUn páramo frío y desolado parece el lugar perfecto para ocultar a un domanaar.\n\n<Maella lanza una mirada poco sutil a Décimo.>', 68974),
(316419, 'esMX', '<La baliza tiene dos botones para seleccionar un destino de teletransporte: Lunargenta o Tormenta del Vacío. Resiste la tentación de pulsar ambos botones a la vez.>', '<La baliza tiene dos botones para seleccionar un destino de teletransporte: Lunargenta o Tormenta del Vacío. Resiste la tentación de pulsar ambos botones a la vez.>', 68974),
(316274, 'esMX', '', 'Gracias a las holohuellas que recuperaste, sabemos de dónde sacan los etéreos los artefactos draenei.\n\nHay una cripta que construyó mi pueblo, debajo de la isla.\n\nLos hal\'hadar están cosechando tanto a los guardianes de su interior como a los espíritus perturbados de los muertos.\n\nSus registros indican que hay múltiples vigilantes dentro de la tumba, pero hasta ahora, sus esfuerzos no han dado frutos.\n\nSi tenemos suerte, quizá podamos interceptar sus operaciones.\n\nTala\'saan encabezará nuestra incursión en la cripta.', 68974),
(316214, 'esMX', '', '<Los ojos de la archimaga Y\'mera se agrandan cuando te quita uno de los cristales.>\n\nLas runas de estos son draénicas, $n. No debería sorprenderme tanto.\n\nLos hal\'hadar son unos carroñeros en lo que respecta a la tecnología. Saquean las ruinas de cualquier mundo al que llegan.\n\nDeben haber encontrado las tecnologías de cristales de nuestro pueblo en otro lugar, al igual que encontraron nuestros engranajes bélicos.\n\nExaminaré esto. Lleva el resto a Kifaan, que está por ahí. Estuvo documentando la tecnología de los hal\'hadar.\n\nSería bueno contar con la opinión de un tecnomante del Consorcio sobre este descubrimiento.', 68974),
(316212, 'esMX', '', '<La Archimaga Y\'mera parece concentrada en su tarea: sus manos se mueven a toda velocidad mientras introduce símbolos rúnicos en la consola.>\n\nCon un poco de suerte y mucho esfuerzo de descifrado, esperamos poder comprender qué pretenden lograr nuestros enemigos en Naigtal.\n\nHay muchas cosas que aprender sobre los hal\'hadar, $ucampeón:campeona;.\n\nNo desperdiciemos esta oportunidad.', 68974),
(314754, 'esMX', '¡Tus enemigos están detrás. ¡Da la vuelta!', '¡Tus enemigos están detrás. ¡Da la vuelta!', 68974),
(313932, 'esMX', '', 'La avizora de fallas Maella observa con desdén la proyección de Décimo.', 68974),
(313749, 'esMX', '', '¿Es hora? ¿La avizora de fallas Maella te envió? ¡Me vendría bien tu ayuda antes de partir!\n\nHe estado trabajando en modificaciones para nuestra tecnología veloluz con un simple camuflaje y esa atadura.\n\nSi los combino, creo que podré cubrir todo nuestro campamento base cuando lleguemos.\n\nPero antes, necesito un sujeto de pruebas invisible para precisar los límites de la atadura.\n\n¿Quieres ayudarme?', 68974),
(310380, 'esMX', 'Exterminar a un imperator domanaar no tiene el mismo impacto que matar a un líder mortal.', '', 68974),
(310377, 'esMX', '', 'Pertinax no volverá a ser un problema gracias a ti, adalid.', 68974),
(310376, 'esMX', 'Y si su \"imperator\" te honra con su presencia, te agradecería que elimines cualquier rastro suyo de este páramo.', '', 68974),
(310375, 'esMX', '', 'Neutralizar la presencia del Vacío aquí le dará un merecido alivio a nuestro pueblo. Siembra el caos, adalid.', 68974),
(310366, 'esMX', 'Luz... vileza... Vacío. La receta perfecta para agravar las tensiones. Qué delicia.', '', 68974),
(309048, 'esMX', 'Los hal\'hadar equiparon sus esquifes voladores con torretas de energía para \"protegerse\". Veamos qué tan protegidos están, ¿qué te parece?', '', 68974),
(309047, 'esMX', 'Sé muy poco sobre estos \"hal\'hadar\", pero, al parecer, son más formidables que la Guardia de las Sombras. Opino que deberías diezmar sus filas para evitar que te aventajen más adelante.', '', 68974),
(309020, 'esMX', '', 'Los exploradores templeluz encontraron pruebas de que aquí existió una vez una criatura del Vacío ancestral. Recoge algunas muestras para nuestra investigación.', 68974),
(309018, 'esMX', 'Tus exploradores más... \"aventureros\" han intentado aprovechar los recursos volátiles de este mundo. Intenta recogerlos sin causar accidentes lamentables.', '', 68974),
(309015, 'esMX', '', 'Si saboteamos la red de portales de los domanaar, evitaremos que invadan Azeroth. Haz lo posible por detenerlos.', 68974),
(309014, 'esMX', 'Para sorpresa de nadie, otra \"amenaza\" pone tu misión en peligro. Destruye, elimina, triunfa.', '', 68974),
(318546, 'esMX', 'El Bancal del Magister siempre ha sido un faro del saber compartido.\n\nUn bastión del conocimiento donde se intercambian ideas sin distinciones ni egos.\n\nSin embargo, por mucho que lo intente, me cuesta mirar a los que han regresado sin sentir...\n\n<El magíster aprieta los dientes y se queda en silencio.>', 'El Bancal del Magister siempre ha sido un faro del saber compartido.\n\nUn bastión del conocimiento donde se intercambian ideas sin distinciones ni egos.\n\nSin embargo, por mucho que lo intente, me cuesta mirar a los que han regresado sin sentir...\n\n<La magíster aprieta los dientes y se queda en silencio.>', 68974),
(318542, 'esMX', '<El noble magíster elfo suspira cuando te acercas.>\n\nPor favor, no me retes por estar aquí... No podría soportar otra mirada fulminante ni otro comentario.\n\nSolo quiero estudiar magia y practicar hechizos nuevos; ¿estoy pidiendo demasiado?\n\n¡Tanto conflicto me está volviendo loco!', '<La noble magíster elfa suspira cuando te acercas.>\n\nPor favor, no me retes por estar aquí... No podría soportar otra mirada fulminante ni otro comentario.\n\nSolo quiero estudiar magia y practicar hechizos nuevos; ¿estoy pidiendo demasiado?\n\n¡Tanto conflicto me está volviendo loca!', 68974),
(317974, 'esMX', 'El dominio y el estudio de la magia siempre ha sido nuestro objetivo. El objetivo de todo magíster.\n\nEspero que nuestros compañeros que tienen la mente más abierta ayuden a los demás a entender nuestras intenciones a la hora de estudiar el Vacío.\n\nY tampoco es que amenazamos con el exilio a quienes no quieran participar de esta cruzada.', 'El dominio y el estudio de la magia siempre ha sido nuestro objetivo. El objetivo de todo magíster.\n\nEspero que nuestros compañeros que tienen la mente más abierta ayuden a los demás a entender nuestras intenciones a la hora de estudiar el Vacío.\n\nY tampoco es que amenazamos con el exilio a quienes no quieran participar de esta cruzada.', 68974),
(317973, 'esMX', 'Según Veldharin, los primeros buscadores de conocimiento investigaron la presencia oscura que sintieron nuestros ancestros en Tirisfal.\n\nNadie sabe qué encontraron, pero parece que solo unos pocos regresaron con la mente intacta.\n\nLo que sea que vieron o encontraron fue suficiente para que Dath\'Remar prohibiera la magia del Vacío.\n\n¿Umbric lo habrá examinado? ¿Nos permitirán hacerlo también?', 'Según Veldharin, los primeros buscadores de conocimiento investigaron la presencia oscura que sintieron nuestros ancestros en Tirisfal.\n\nNadie sabe qué encontraron, pero parece que solo unos pocos regresaron con la mente intacta.\n\nLo que sea que vieron o encontraron fue suficiente para que Dath\'Remar prohibiera la magia del Vacío.\n\n¿Umbric lo habrá examinado? ¿Nos permitirán hacerlo también?', 68974),
(317972, 'esMX', '<El magíster suspira cuando te acercas.>\n\nPor favor, no me retes por estar aquí... No podría soportar otra mirada fulminante ni otro comentario.\n\nSolo quiero estudiar magia y practicar hechizos nuevos; ¿estoy pidiendo demasiado?\n\nTanto conflicto me está volviendo loco, ¡y eso que miré de lleno un agujero negro!', '<La magíster suspira cuando te acercas.>\n\nPor favor, no me retes por estar aquí... No podría soportar otra mirada fulminante ni otro comentario.\n\nSolo quiero estudiar magia y practicar hechizos nuevos; ¿estoy pidiendo demasiado?\n\nTanto conflicto me está volviendo loca, ¡y eso que miré de lleno un agujero negro!', 68974),
(317917, 'esMX', 'Honestamente, no sé si siquiera tuvo esa intención.\n\nSu traición contra la Asamblea y contra nuestro pueblo fue repugnante, pero no creo que quiera infligirle daño al Omnium.\n\nMe extrañaría que quisiera destruir un repositorio de conocimiento prohibido al que se le negó acceso durante tanto tiempo.\n\nEn todo caso, habría esperado que intentara robarse el Omnium entero.\n\nQuizá por eso se conformó con solo una parte.', '', 68974),
(317753, 'esMX', '<Entrecierra sus ojos vidriosos.>\n\nUna... pregunta adecuada, supongo.\n\nEs... Digo, era un nodo de conocimiento estrictamente prohibido, según lo decretó Dath\'Remar.\n\nCuando llegamos por primera vez a la costa de Tirisfal, nuestros ancestros encontraron una oscuridad que se aferraba a esta tierra.\n\nLos susurros enloquecieron a muchos, se alimentaban de nuestra paranoia e instigaban el miedo y los celos entre nuestros hermanos exhaustos.\n\nDath\'Remar quería comprender de dónde venía esta magia y envió al primero de los Buscadores.\n\nPocos saben qué fue lo que encontraron o descubrieron, pero bastó para que Dath\'Remar interrumpiera su estudio.\n\nSolo a los magísteres más experimentados y de mayor confianza se les permitía explorar el conocimiento que albergaba el Magimódulo del Vacío.', '', 68974),
(317750, 'esMX', '¡Excelente pregunta! Veamos...\n\nTenemos el Magimódulo Arcana, por supuesto. Miles de años de conocimiento altonato le concedieron a nuestro incipiente pueblo los recursos para prosperar en esta tierra nueva.\n\nTenemos los Magimódulos de fuego y de otros elementos, los fundamentos naturales de nuestro propio mundo.\n\nTenemos una colección curiosa de conocimiento sagrado dentro del Magimódulo de Luz. Los sumos sacerdotes de Lunargenta contribuyeron mucho a su conocimiento.\n\nY, como todos preguntan, también están los Magimódulos prohibidos...\n\nEl Vacío. La magia vil. La nigromancia… aunque imagino que algunas de las restricciones sobre estos podrían... flexibilizarse.\n\n<Veldharin frunce el ceño, sumido en sus pensamientos.>', '', 68974),
(317749, 'esMX', 'Te remito a la placa que está ahí en el Omnium. Allí se resumen las intenciones de Dath\'Remar de forma muy acertada.\n\nPero, para resumir, tenía muchas razones, ambiciones audaces y un propósito tan claro como el agua de Canción Eterna.\n\nDath\'Remar vivió mucho en su juventud y nunca temió enfrentarse a las fuerzas mágicas de nuestro mundo.', '', 68974),
(317748, 'esMX', '¡Por supuesto que sí, y no solo por el Omnium!\n\nPerdí a dos hermanos y a mi querida hermana cuando la ciudad cayó. Los tres eran magísteres...\n\nIntenté asistir al joven príncipe para revivirlo... ¿Despertarlo? Estaba tan... frío.\n\nPero no importaba lo que intentáramos... Simplemente se negaba a reaccionar. Ni siquiera respondió con el código llave.\n\nDespués de que lo sellaran, intenté ayudar a los magísteres sobrevivientes a restaurar el Bancal... pero me insistieron en que descansara.\n\nY así lo hice, por muchos años. Algunos... no tan buenos. Sin embargo, he regresado y el joven Rommath no estaba de humor para intentar detenerme.\n\n¡Salir del retiro era justo lo que necesitaba después de tantos años!', '', 68974),
(317746, 'esMX', 'Bueno, cuando insistí en que hicieras una pregunta, me refería a preguntas sobre el Omnium, no sobre mí. Pero si tanto te interesa...\n\nSoy el custodio Veldharin, nombrado guardián del conocimiento por el gran magíster... Ah, ¿quién era?\n\nLa gran magíster Mo... No, ella no. Ah... bueno, da igual. Hace tantos grandes magísteres que ya perdí la cuenta.\n\nDespués de la Segunda Guerra, me... invitaron a retirarme. Al parecer, Anasterian quería que \"disfrutara los muchos días que me quedaban por delante\".\n\nFue su manera de decir que ya estaba muy viejo para el puesto. Así que me mudé con mi hija, Elsharin.\n\nElla sirvió como buscadora del conocimiento y embajadora magisterial del Sagrario del Mago en Ventormenta.', '', 68974),
(317744, 'esMX', '¡Te damos la bienvenida al Licáneo!\n\n¡Estás en presencia del conocimiento ilimitado y el potencial mágico infinito!\n\nPor supuesto, me refiero al Omnium Caminante del Sol. \n\nNo soy más que su guardián, y mi trabajo es responder las preguntas de todos los jóvenes magísteres y guiarlos en su viaje mágico y académico.\n\nNo dudes en preguntar si tienes alguna duda.', '', 68974),
(317738, 'esMX', '¿Por qué les dirán \"magimódulos\"? En teoría son un adminículo del Omnium, por lo que deberían llamarse Omnicul...\n\nBueno, hay maná involucrado, así que bien podrían ser Manácul...\n\nAh, ya entiendo.', '¿Por qué les dirán \"magimódulos\"? En teoría son un adminículo del Omnium, por lo que deberían llamarse Omnicul...\n\nBueno, hay maná involucrado, así que bien podrían ser Manácul...\n\nAh, ya entiendo.', 68974),
(317730, 'esMX', 'No veía tanto caos mágico en el Bancal desde... bueno... tu incursión con el magíster Umbric.\n\n<El rompedora de hechizos te observa de arriba abajo.>\n\nCompórtate esta vez, ¿sí?', 'No veía tanto caos mágico en el Bancal desde... bueno... tu incursión con el magíster Umbric.\n\n<La rompedora de hechizos te observa de arriba abajo.>\n\nCompórtate esta vez, ¿sí?', 68974),
(317724, 'esMX', 'Compórtate en estos salones, $c. \n\nPuede que este sea el Bancal del Magister, pero las normas de la magia aún se hacen cumplir con rigor.', 'Compórtate en estos salones, $c. \n\nPuede que este sea el Bancal del Magister, pero las normas de la magia aún se hacen cumplir con rigor.', 68974),
(317723, 'esMX', '<El rompedor de hechizos te observa con los ojos entrecerrados y esboza una ligera sonrisa de suficiencia.>\n\nNo te preocupes, $n. No desenfundaré mi guja contra ti.\n\nTengo entendido que la última vez que estuviste aquí tenías la autoridad del señor regente. Que quede claro que mi reacción no fue personal.\n\nYo cumplo con el juramento de los rompedores de hechizos y... esa secuencia de eventos desafortunados en el Bancal debió resolverse entre las cortes y los magísteres, no entre tú y yo.\n\nDe cualquier manera, te agradezco que no le hayas puesto fin a mi vida.', '', 68974),
(317722, 'esMX', '<Rommath entrecierra los ojos por un instante.>\n\nUmbric y sus… seguidores deberán acatar las regulaciones en lo que respecta al Omnium.\n\nNo permitiré una exhibición mágica con los horrores del Vacío solo porque los ren\'dorei son incapaces de seguir las reglas.\n\nNo obstante, aunque confíe poco en la senda que eligió Umbric, podría estar dispuesto al menos a confiar en él... por el momento.\n\nEl control del Vacío que, según él, su gente ha conseguido, podría permitir discusiones más… informadas en lo que respecta al Magimódulo del Vacío.\n\n¡Pero no permitiré que la magia del Vacío se convierta en un nuevo plan de estudios para los magísteres de este bancal!', '', 68974),
(317721, 'esMX', 'Solo los magísteres tienen permitido estudiar el conocimiento que aquí reside, e incluso bajo ciertas restricciones.\n\nLas normas y los reglamentos los fijó el propio Dath\'Remar hace generaciones.\n\nHizo esto para garantizar que, a medida que descubriéramos y catalogáramos magia nueva y peligrosa, también nos protegiéramos de la naturaleza impredecible de estas fuerzas.\n\nDicho esto, hubo un tiempo en que acceder al Magimódulo Vil estuvo estrictamente prohibido.\n\nQuién hubiera imaginado que los tiempos cambiarían tan rápido...', '', 68974),
(317719, 'esMX', '<Umbric sonríe y dirige la mirada hacia Rommath.>\n\nPuede que Rommath... apenas tolere mi investigación, pero el Omnium siempre contó con la protección de resguardos y regulaciones.\n\nNunca se trató de un compendio de libre acceso sobre todo lo relacionado con la magia, afortunadamente.\n\nMe estremezco de pensar en lo que Dar\'Khan podría haber logrado si hubiera conseguido acceder a él.\n\nLas reglas vigentes existen desde la época de Dath\'Remar.\n\nSus primeros encuentros con el Vacío o la devastación que presenció con energía vil durante la Guerra de los Ancestros son precisamente los motivos por los que se prohibieron esos tipos de magia.\n\nDicho esto, quizá haya algunas conversaciones pendientes.', '', 68974),
(317717, 'esMX', 'Es una pregunta que todos nos hemos hecho desde que se quedó en silencio.\n\nNadie sabe con exactitud qué ocurrió. Lo único que sabemos es el estado en que lo encontraron.\n\nYo no estaba aquí al momento de la caída del Bancal... ni en la llegada de Dar\'Khan... pero sí fui testigo de las secuelas.\n\nNunca había visto el Omnium tan vacío... sin un atisbo de poder, ni un magimódulo a la vista.\n\nUn armazón desolado y silente. Fue inquietante, cuanto menos.', '', 68974),
(317715, 'esMX', 'Cuando lo encontramos solo era un armazón vacío en medio de los restos. No había magimódulos ni brillo rúnico.\n\nAparte de los restos que dejó la masacre de Dar\'Khan, no parecía tener vida.\n\nLos magimódulos se crearon como extensiones del Omnium. Jamás los consideramos piezas que podían desaparecer.\n\nCuando la reliquia despertó y los magimódulos reaparecieron, notamos que la matriz central estaba vacía.\n\nEra una anomalía que jamás habíamos visto.\n\nEl magimódulo al que se había accedido por última vez había desaparecido o lo habían destruido. O bien, como en este caso, lo habían robado.', '', 68974),
(317714, 'esMX', 'Al principio, así fue. \n\nSabíamos que había acudido al Bancal para masacrar a la convocación. La evidencia quedó desparramada en las paredes y en el mismo Omnium.\n\nPero cuando registramos sus estudios y su hogar, solo descubrimos su obsesión por las magias más oscuras.\n\nUmbric luego señaló que las motivaciones de Drathir eran el poder y el conocimiento, y que dañar el Omnium parecía ir en contra de sus... ambiciones.', '', 68974),
(317713, 'esMX', 'Me temo que... no puedo responder a ese planteo.\n\nPero intentamos todo para reanimar el Omnium. Ni siquiera el código llave del Caminante del Sol tuvo efecto.\n\nKael\'thas estaba... devastado.\n\nÉl, al igual que todos, había perdido mucho en muy poco tiempo. \n\nEstaba desesperado por encontrar respuestas para nuestro sufrimiento. Para nuestro pueblo.\n\nEl conocimiento que contenía el Omnium quizá nos podría haber ayudado... Podría incluso haber guiado al príncipe.\n\nPero su silencio nos dejó estancados sin salida.', '', 68974),
(316792, 'esMX', 'Código llave Caminante del Sol no identificado. Marca de eco exacto activada.', 'Código llave Caminante del Sol no identificado. Marca de eco exacto activada.', 68974),
(315312, 'esMX', 'Esta es la Aguja de la Estrella del Alba, el hogar de la infancia de Dar\'Khan Drathir. En una época fue un lugar tranquilo y agradable.\n\nLuego de que me exiliaran de Lunargenta, rastreé varios fragmentos de la investigación de Dar\'Khan sobre el Vacío hasta llegar aquí.\n\nAl parecer, realizó una gran parte de su actividad en secreto. En la cima de esta torre, abrí por primera vez la falla que conduce a Telogrus.\n\nNo tenía idea de que este lugar aún ocultaba más secretos...', '', 68974),
(314998, 'esMX', 'Nunca nombramos buscadores que no sean magísteres, pero tú... estás más que $Ucalificado:calificada;.\n\nComo $Ubuscador:buscadora, Umbric y yo te asignaremos tareas de investigación.\n\nComo recompensa por cumplir los objetivos, te concederemos una serie de encantamientos rúnicos para potenciar tus propios poderes.\n\nEncontrarás las runas en tu folio del Omnium. Por supuesto, tú decidirás cuál quieres mejorar.\n\n¿Alguna pregunta?', '', 68974),
(314900, 'esMX', '<Rommath eleva la mirada hacia el Omnium silencioso.>\n\nFalta poco. Ahora que tenemos el código llave de Belo\'vir y el Magimódulo del Vacío perdido que tú y Umbric han recuperado, solo queda una tarea pendiente.\n\nEs ahora o nunca, $n. ¿Estás $ulisto:lista;?', '', 68974),
(314899, 'esMX', 'Estudié el Omnium durante varios años. Como todos los magísteres que me precedieron, aprendí todo lo que tenía para ofrecer sobre runas, hechizos e incluso encantamientos.\n\nEl día que calló fue un día oscuro por muchas razones. Nunca imaginé que volvería a cobrar vida. Es increíble lo lejos que hemos llegado.', '', 68974),
(314791, 'esMX', 'Al parecer, Belo\'vir dejó instrucciones para acceder a su bóveda... Instrucciones que me han estado esperando durante mucho tiempo.\n\nConociendo a mi predecesor, sin duda solo se podrá abrir utilizando algún método que sea digno de su dominio del hechizo de reflejos exactos.\n\nNecesitaremos dividirnos para afrontar este desafío. Subiré a mi oficina y me encargaré de los resguardos más complejos.\n\n¿Podrías ayudar a mis reflejos exactos a descifrar los tres que se encuentran en los niveles externos?', '', 68974),
(314746, 'esMX', 'Me pregunto cuánto tiempo habrá dedicado Dar\'Khan a buscar los secretos prohibidos del Magimódulo del Vacío.\n\nCuando nos unimos por primera vez a los magísteres, nos dieron una lección sobre las escuelas de magia y los magimódulos asociados que estaban estrictamente prohibidos para la asamblea general.\n\nDar\'Khan ya había mostrado una inclinación por el Vacío cuando dábamos nuestros primeros pasos en Dalaran, así que era evidente que tenía algún tipo de fascinación.\n\n¿Acaso la codicia lo invadió desde la primera vez que entramos en el Licáneo?\n\n¿O fue una decisión osada de último minuto la que lo llevó a masacrar a sus hermanos en el Bancal?', '', 68974),
(314744, 'esMX', 'En una época, creí que había descubierto todos los secretos que Dar\'Khan había ocultado en este lugar. Los eventos de hoy han sido verdaderamente... inesperados.\n\nPara tener algo de cautela, y porque sé que Rommath preguntará al respecto, voy a asegurarme de que no haya quedado nada escondido en algún recoveco.\n\nMe dirigiré al Bancal del Magister luego de limpiar nuestro ritual. Búscame ahí una vez que hayas ayudado a Rommath a recuperar el código llave de Belovir.', '', 68974),
(314678, 'esMX', 'Mis sospechas fueron ciertas... ¿Puedes sentirlo en el aire, $n? Ese pulso frío y distante... como si fuera el eco de un latido.\n\nCreo que podría ser el componente que estamos buscando, oculto en algún lugar fuera de nuestro alcance.\n\nCon el hechizo adecuado y un poco de concentración, el Vacío puede revelar los secretos que Dar\'Khan aún oculta aquí.\n\nMientras tú conectas los anclajes, yo me encargaré de finalizar este hechizo.\n\nTen cuidado: el Vacío ya nos atrae y nos llama hacia nuestro destino.', '', 68974),
(310354, 'esMX', 'Tendremos que desactivar sus medidas de seguridad. Me reuniré con $unuestro:nuestra; adalid ahí.', '', 68974),
(310059, 'esMX', 'Aunque se tratara de magia arcana, vil, o incluso de la Luz o... el Vacío, Dath\'Remar creó el Omnium para preservar el conocimiento.', '', 68974),
(317919, 'esMX', 'Imagino que muchos comparten tu inquietud.\n\nPor lo general, derivo todas las consultas a nuestro recientemente reincorporado guardián del conocimiento, el custodio Veldharin.\n\nPero, dado el papel que has desempeñado en la restauración del Omnium, saciaré tu curiosidad.', '', 68974),
(317754, 'esMX', 'Ah, sí. El Magimódulo Vil. Un nodo prohibido de conocimiento, al menos en el pasado.\n\nLa magia vil fue una de las primeras magias que Dath\'Remar consideró como catalizador para crear el Omnium.\n\nVio su potencial... y su horror durante los días de los altonato. Vio las criaturas del más allá que conjuraban magia vil.\n\nCuando llegó el momento, vio la verdad destructiva tanto de la magia vil como de la arcana en esos últimos días de la Guerra de los Ancestros.\n\nJamás volvería a permitir que una fuerza tan destructiva y desconocida atacara por sorpresa a su gente.\n\nCon el tiempo, el conocimiento sobre la magia vil y la Legión Ardiente se compartió entre el magíster y el Consejo de Tirisfal.\n\nPero, con excepción de unos pocos selectos, el estudio del Magimódulo Vil estaba prohibido.\n\nAh, cuánto ha cambiado todo...', '', 68974),
(317573, 'esMX', 'Este mundo... Todo su potencial... Ahora es mío.', '', 68974),
(309931, 'esMX', '¡Forestales, prepárense! ¡Enséñenles a estos monstruos por qué fuimos elegidos para proteger el Enclave!', '¡Forestales, prepárense! ¡Enséñenles a estos monstruos por qué fuimos elegidos para proteger el Enclave!', 68974),
(307084, 'esMX', 'Ah, $n. \n\nQué bueno ver una cara agradable en esta mesa. Toleran que esté aquí, en mi ciudad, de nuevo, pero recuerda mis palabras: en cualquier momento Rommath lanzará uno de sus misiles especiales de traslación de nuevo.\n\nVerás, combinó misiles de traslación con misiles arcanos para darle una lección a cualquiera lo bastante necio como para enfrentarlo en un duelo de magos en el pasado. \n\nNo quiere admitirlo, pero fui yo quien le enseñó a ponerles a los misiles un hechizo de invisibilidad para que no se los vea venir. \n\nDe todos modos, Lor\'themar me dio permiso para estar aquí, y estoy disfrutando de la incomodidad que mi presencia genera en algunos.', '', 68974),
(306595, 'esMX', 'Mm... Hay que avisarle a Lor\'themar lo que pasó. Tú ve primero.', '', 68974),
(304405, 'esMX', 'En tiempos de guerras y conflictos, nuestros protectores ancestrales han demostrado ser una fuerza imparable en el campo de batalla.\n\nEl único problema es que despertarlos implica un gran esfuerzo.\n\nMe encargaré de que los auxiliares de batalla del anciano Glaucorteza te sigan. Busca piedras o rocas que el anciano pueda arrojar contra nuestros enemigos.\n\nSe rehúsa a despertar hasta que tenga algo que arrojar.', 'En tiempos de guerras y conflictos, nuestros protectores ancestrales han demostrado ser una fuerza imparable en el campo de batalla.\n\nEl único problema es que despertarlos implica un gran esfuerzo.\n\nMe encargaré de que los auxiliares de batalla del anciano Glaucorteza te sigan. Busca piedras o rocas que el anciano pueda arrojar contra nuestros enemigos.\n\nSe rehúsa a despertar hasta que tenga algo que arrojar.', 68974),
(303273, 'esMX', '', 'Los protectores ancianos ofrecen un potencial de asedio poderoso en la batalla que puede diezmar las filas defensivas del enemigo.\n\nLa Horda está muy familiarizada con su poder destructivo.', 68974),
(300503, 'esMX', '', 'Eso no debería ser posible. Era un mensaje mágico que le envié a Ulen, el senescal al mando en mi ausencia. Tal vez haya problemas en Suramar.', 68974),
(292933, 'esMX', 'Bueno... le dedicaste mucho trabajo, y te lo ganaste.', '', 68974),
(289958, 'esMX', '', 'El Pacto de Plata vuelve a Lunargenta por última vez.', 68974);
